from collections import deque

graf = {
    "A": ["B", "C"],
    "B": ["A", "D"],
    "C": ["A", "D", "E"],
    "D": ["B", "C", "F"],
    "E": ["C", "F"],
    "F": ["D", "E"],
}


def bfs(baslangic):
    mesafe = {baslangic: 0}
    kuyruk = deque([baslangic])
    while kuyruk:
        dugum = kuyruk.popleft()
        for komsu in graf[dugum]:
            if komsu not in mesafe:
                mesafe[komsu] = mesafe[dugum] + 1
                kuyruk.append(komsu)
    return mesafe


print(bfs("A"))
